code.cpp:
class Solution {
public:
    string toLowerCase(string s) {
        for (int i = 0; i < (int)s.size(); i++) {
            if (s[i] >= 'A' && s[i] <= 'Z') {
                s[i] += 32;
            }
        }
        return s;
    }
};
